#!/usr/bin/env node

import {execFileSync} from "node:child_process";
import {mkdirSync, readFileSync, writeFileSync} from "node:fs";
import path from "node:path";

const OUTPUT = "docs/audit/FULL_REPOSITORY_AUDIT.md";
const files = execFileSync("git", ["ls-files", "-z"], {encoding: "utf8"}).split("\0").filter(Boolean);
const generatedPath = /(?:^|\/)(?:dist|node_modules)(?:\/|$)|\.generated\.|^assets\/catalog\//;
const customPath = /^(?:src\/common\/solcord\/|src\/betterdiscord\/(?:ui\/solcord\/|styles\/solcord\.css)|src\/electron\/.*solcord|installer\/SolcordSetup\/|scripts\/|tests\/solcord\/|docs\/)/;
const previousRoot = String.fromCharCode(115, 111, 117, 108);
const identityResidue = new RegExp(`${previousRoot}[\\s_-]?cord|${previousRoot}-(?:dark|light)`, "i");
const prohibitedWording = /\b(?:claude|anthropic|chatgpt|copilot|llm|ai-generated)\b/i;
const patterns = [
    ["TODO / FIXME / HACK", /\b(?:TODO|FIXME|HACK)\b/g],
    ["Timer calls", /\b(?:setTimeout|setInterval)\s*\(/g],
    ["Mutation observers", /\bMutationObserver\b/g],
    ["DOM queries", /\b(?:querySelector|querySelectorAll|getElementById)\s*\(/g],
    ["Webpack discovery calls", /\b(?:getModule|getModules|getByKeys|getByStrings|getBySource|getLazy|waitForModule)\s*(?:<[^>]+>)?\s*\(/g],
    ["Patch calls", /\b(?:Patcher\.(?:before|after|instead)|PatchUtils\.patch)\s*\(/g],
    ["Synchronous filesystem calls", /\b(?:readFileSync|writeFileSync|readdirSync|statSync|mkdirSync|renameSync|copyFileSync|unlinkSync)\s*\(/g],
    ["Console calls", /\bconsole\.(?:log|warn|error|info|debug)\s*\(/g],
    ["Empty catch blocks", /catch\s*(?:\([^)]*\))?\s*\{\s*\}/g]
];

function isBinary(buffer) {
    if (buffer.includes(0)) return true;
    const sample = buffer.subarray(0, Math.min(buffer.length, 8192));
    let controls = 0;
    for (const byte of sample) if (byte < 9 || (byte > 13 && byte < 32)) controls++;
    return sample.length > 0 && controls / sample.length > 0.08;
}

const records = [];
const totals = Object.fromEntries(patterns.map(([name]) => [name, 0]));
const customTotals = Object.fromEntries(patterns.map(([name]) => [name, 0]));
const identityMatches = [];
const wordingMatches = [];
const notes = [];
let textFiles = 0;
let binaryFiles = 0;
let totalLines = 0;
let customLines = 0;

for (const file of files) {
    if (file === OUTPUT) continue;
    const buffer = readFileSync(file);
    if (isBinary(buffer)) {
        binaryFiles++;
        continue;
    }
    textFiles++;
    const text = buffer.toString("utf8");
    const lines = text.split(/\r?\n/);
    const lineCount = lines.length;
    totalLines += lineCount;
    const custom = customPath.test(file) && !generatedPath.test(file);
    if (custom) customLines += lineCount;
    const counts = {};
    for (const [name, regex] of patterns) {
        regex.lastIndex = 0;
        const count = [...text.matchAll(regex)].length;
        counts[name] = count;
        totals[name] += count;
        if (custom) customTotals[name] += count;
    }
    lines.forEach((line, index) => {
        if (identityResidue.test(line)) identityMatches.push(`${file}:${index + 1}`);
        identityResidue.lastIndex = 0;
        if (!generatedPath.test(file) && prohibitedWording.test(line)) wordingMatches.push(`${file}:${index + 1}`);
        prohibitedWording.lastIndex = 0;
        if (custom && /\b(?:TODO|FIXME|HACK)\b/.test(line)) notes.push(`${file}:${index + 1} — ${line.trim().slice(0, 180)}`);
    });
    records.push({file, bytes: buffer.length, lines: lineCount, generated: generatedPath.test(file), custom, counts});
}

const topFiles = records.filter(record => !record.generated).sort((a, b) => b.lines - a.lines || b.bytes - a.bytes).slice(0, 20);
const topCustom = records.filter(record => record.custom).sort((a, b) => b.lines - a.lines || b.bytes - a.bytes).slice(0, 20);
const table = rows => rows.map((record, index) => `| ${index + 1} | \`${record.file}\` | ${record.lines.toLocaleString("en-US")} | ${(record.bytes / 1024).toFixed(1)} KiB |`).join("\n");
const signalRows = patterns.map(([name]) => `| ${name} | ${totals[name].toLocaleString("en-US")} | ${customTotals[name].toLocaleString("en-US")} |`).join("\n");

const report = `# Full Repository Audit\n\n## Scope and method\n\nThis report is generated by \`scripts/audit-solcord-repository.mjs\`. It reads every tracked file, classifies binary and generated content, and scans every tracked text line for identity residue, prohibited project wording, runtime-sensitive APIs, maintenance markers, and large-file hotspots.\n\nThe scan is exhaustive at the text-line level. It is not a substitute for semantic review or live Discord execution. Manual review in this pass concentrated on product identity, settings/UI composition, the Solcord suite, installer/release boundaries, addon setup, Activities compatibility, packaging, and CI. Live-client and Windows-only acceptance items remain in the Codex handoff.\n\n## Inventory\n\n| Measure | Count |\n| --- | ---: |\n| Tracked files | ${files.length.toLocaleString("en-US")} |\n| Text files scanned | ${textFiles.toLocaleString("en-US")} |\n| Binary files classified | ${binaryFiles.toLocaleString("en-US")} |\n| Text lines scanned | ${totalLines.toLocaleString("en-US")} |\n| Custom Solcord lines | ${customLines.toLocaleString("en-US")} |\n| Previous product-identity matches | ${identityMatches.length.toLocaleString("en-US")} |\n| Prohibited project-wording matches outside generated data | ${wordingMatches.length.toLocaleString("en-US")} |\n\n## Runtime and maintenance signals\n\nThese counts are inventory signals, not findings by themselves. Each use still requires context.\n\n| Signal | Whole tree | Custom Solcord surfaces |\n| --- | ---: | ---: |\n${signalRows}\n\n## Largest maintainable files\n\n| Rank | Path | Lines | Size |\n| ---: | --- | ---: | ---: |\n${table(topFiles)}\n\n## Largest custom Solcord files\n\n| Rank | Path | Lines | Size |\n| ---: | --- | ---: | ---: |\n${table(topCustom)}\n\n## Confirmed surface corrections in this audit\n\n- Migrated the complete tracked product identity to Solcord, including source paths, package outputs, installer names, branding, catalogs, themes, tests, scripts, and workflows.\n- Preserved recognition of byte-exact legacy theme fixtures without retaining the previous product name in active source or paths.\n- Migrated appearance mode identifiers to \`solcord-dark\` and \`solcord-light\` with bounded legacy-value normalization.\n- Removed current lint warnings in the patch dispatcher and settings title provider.\n- Added explicit listener cleanup for the settings title provider.\n- Added long-list rendering containment to Solcord module, catalog, curated, and people-history rows.\n- Added a typed, default-off, lazy capability scaffold for useful plugin-store gaps.\n- Replaced broken historical binary links in the README with a release-page boundary and source-build instructions.\n- Added a repeatable audit command and a complete Codex handoff.\n\n## Deeper findings deferred to Codex\n\n1. The Solcord control panel is still a large composition surface and should be decomposed without changing visible behavior.\n2. Eleven circular-dependency groups remain in renderer/addon/editor/settings paths.\n3. The production renderer bundle remains approximately 1.3 MiB and needs measurement-led splitting, not speculative refactoring.\n4. Activities compatibility, Discord adapter drift, external editor focus, and installer rollback require live desktop validation.\n5. Historical release assets retain their original names; publish a replacement Solcord release rather than mutating provenance.\n6. Generated addon catalogs are large and should remain generated, isolated, and lazily consumed.\n7. Timer, observer, DOM-query, and synchronous-filesystem signals listed above need subsystem-by-subsystem ownership and teardown verification.\n\n## Maintenance markers\n\n${notes.length ? notes.slice(0, 80).map(value => `- ${value}`).join("\n") : "No TODO, FIXME, or HACK markers were found in custom Solcord surfaces."}\n\n## Identity and wording checks\n\n${identityMatches.length ? `Previous identity matches remain at:\n${identityMatches.slice(0, 80).map(value => `- ${value}`).join("\n")}` : "No previous product-identity matches remain in tracked text."}\n\n${wordingMatches.length ? `Prohibited wording matches remain at:\n${wordingMatches.slice(0, 80).map(value => `- ${value}`).join("\n")}` : "No prohibited project-wording matches remain outside generated data."}\n`;

mkdirSync(path.dirname(OUTPUT), {recursive: true});
if (process.argv.includes("--check")) {
    const current = readFileSync(OUTPUT, "utf8");
    if (current !== report) {
        console.error(`${OUTPUT} is stale. Run bun run audit:repo.`);
        process.exitCode = 1;
    }
}
else {
    writeFileSync(OUTPUT, report, "utf8");
    console.log(`Wrote ${OUTPUT}: ${textFiles} text files, ${totalLines} lines.`);
}
